rules=json.loads((OLD/'private/scoring_rules.json').read_text());rules.update(columns=cols,row_key=['withdrawn_OrganizationIdentifier','withdrawn_ActivityIdentifier','start_year','end_year'],sorting='withdrawn activity ID, start year, end year; P.O.A. on complete scenario/interval identities; fewer2common=>0')
rules['fields']['cohort_station_ids']={'type':'id_list','semantics':'Compare the membership set; semicolon/comma/whitespace separators and member order are presentation equivalents. Preserve individual identifiers. Repeated identical members do not add membership.'};rules['sentinels']='Declared empty-post-frontier sentinel is meaningful missing data; NONE/NA exactly as public task. Actual source recomputation determines whether any exists.';dump(P/'scoring_rules.json',rules)
