g=json.loads((OLD/'private/state_graph.json').read_text());g['nodes']=['original_station_universe','original_activity_panels','original_year_support','original_all_interval_frontier','independent_withdrawal_identity','post_withdrawal_year_support','post_withdrawal_all_interval_frontier','full_design_set_change_test','post_trial_interval_cohort_and_withdrawn_season','remaining_cohort_event_minimum','same_activity_companion_measurements','scenario_specific_sorted_output'];g['edges']=[{'from':x,'to':y} for x,y in zip(g['nodes'],g['nodes'][1:])];g['required_state_retention']='Restore the complete original record between trials. Each withdrawal changes its own support state, global frontier, cohort, year range and season-specific candidate events. Do not reuse original frontier intervals or minimum events as the universe of post-withdrawal choices.';g['retrieval_limit']='Legal complete exports may make this entirely local computation. No unavoidable adaptive network sequence is claimed. All added dependencies need real counterfactual effects and independent empirical difficulty tests.';dump(P/'state_graph.json',g)
